const dilemmas=[{title:'기억을 지울 권리',tag:'생명윤리 × 정체성',text:'고통스러운 기억만 지우는 기술이 생겼다. 기억을 지우면 고통은 줄지만, 그 경험에서 비롯된 판단과 관계도 달라진다. 선택권은 어디까지 보장되어야 할까?',a:'개인의 선택을 우선한다',b:'사회적 보호 장치가 우선이다',views:['자율성: 삶의 경험을 어떻게 다룰지 결정할 권리를 중시한다.','돌봄: 절박한 상황에서의 결정이 충분히 자발적인지 살핀다.','정체성: 기억의 변화가 미래의 나와 주변 관계에 미칠 영향을 묻는다.'],prompt:'기억을 삭제하지 않고 고통만 줄이는 제3의 방법을 설계해 봐.'},{title:'공정한 추천 알고리즘',tag:'기술 × 도덕',text:'추천 시스템이 대다수의 만족도를 높이지만 소수의 취향은 거의 노출하지 않는다. 전체 만족도가 높은 시스템은 공정할까?',a:'전체 만족도를 우선한다',b:'소수의 노출 기회를 보장한다',views:['공리주의: 총체적인 만족과 그 분포를 함께 검토할 수 있다.','권리 관점: 소수의 참여와 표현의 기회에 주목한다.','무지의 베일: 자신의 취향이 다수인지 모른다면 어떤 규칙을 택할까?'],prompt:'만족도와 다양성을 동시에 높이는 추천 규칙을 하나 만들어 봐.'},{title:'한정된 치료 기회',tag:'생명윤리 × 정의',text:'치료 기회가 한정되어 있다. 가장 위급한 사람, 치료 효과가 클 사람, 가장 오래 기다린 사람 중 누구를 먼저 도와야 할까?',a:'가장 위급한 사람',b:'치료 효과가 가장 클 사람',views:['필요: 지금 가장 심각한 위험에 놓인 사람을 우선한다.','효과: 같은 자원으로 얻을 수 있는 건강상의 이익을 고려한다.','절차: 기준을 투명하게 공개하고 이의를 제기할 기회를 보장한다.'],prompt:'둘 중 하나를 고르지 않고 여러 기준을 결합하는 절차를 만들어 봐.'}];

